create table if not exists public.receivable_payments(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id) on delete restrict,amount numeric(14,2) not null check(amount>0),method public.payment_method not null,paid_at date not null default current_date,reference text,notes text,cash_session_id uuid references public.cash_sessions(id),cash_movement_id uuid references public.cash_movements(id),created_by uuid references public.profiles(id),created_at timestamptz not null default now());create index if not exists receivable_payments_sale_date_idx on public.receivable_payments(sale_id,paid_at desc);
alter table public.warranties add column if not exists sale_id uuid references public.sales(id) on delete restrict;alter table public.warranties add column if not exists product_id uuid references public.products(id) on delete restrict;alter table public.warranties add column if not exists serial_number text;alter table public.warranties add column if not exists sold_at date;alter table public.warranties add column if not exists warranty_months integer;alter table public.warranties add column if not exists expires_at date;alter table public.warranties add column if not exists notes text;alter table public.warranties add column if not exists updated_at timestamptz not null default now();alter table public.warranties add column if not exists created_by uuid references public.profiles(id);update public.warranties w set sale_id=si.sale_id,product_id=si.product_id,sold_at=coalesce(w.starts_at,current_date),expires_at=coalesce(w.ends_at,current_date),warranty_months=greatest(0,((extract(year from age(coalesce(w.ends_at,current_date),coalesce(w.starts_at,current_date)))*12)+extract(month from age(coalesce(w.ends_at,current_date),coalesce(w.starts_at,current_date))))::integer),notes=coalesce(w.terms,w.claim_notes),serial_number=ps.serial_number from public.sale_items si left join public.product_serials ps on ps.id=si.serial_id where w.sale_item_id=si.id and (w.sale_id is null or w.product_id is null or w.sold_at is null or w.expires_at is null);create index if not exists warranties_expires_idx on public.warranties(status,expires_at);
create table if not exists public.warranty_claims(id uuid primary key default gen_random_uuid(),warranty_id uuid not null references public.warranties(id) on delete restrict,claim_date date not null default current_date,description text not null check(length(trim(description))>0),resolution text,status text not null default 'open' check(status in ('open','in_review','resolved','rejected')),created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index if not exists warranty_claims_warranty_date_idx on public.warranty_claims(warranty_id,claim_date desc);
alter table public.receivable_payments enable row level security;alter table public.warranties enable row level security;alter table public.warranty_claims enable row level security;drop policy if exists "Active users read receivable payments" on public.receivable_payments;create policy "Active users read receivable payments" on public.receivable_payments for select to authenticated using(public.is_active_user());drop policy if exists "Managers record receivable payments" on public.receivable_payments;create policy "Managers record receivable payments" on public.receivable_payments for insert to authenticated with check(public.is_active_user() and public.has_role(array['owner','admin','cashier']::public.app_role[]));drop policy if exists "Active users read warranties" on public.warranties;create policy "Active users read warranties" on public.warranties for select to authenticated using(public.is_active_user());drop policy if exists "Staff manage warranties" on public.warranties;create policy "Staff manage warranties" on public.warranties for all to authenticated using(public.is_active_user() and public.has_role(array['owner','admin','cashier','technician']::public.app_role[])) with check(public.is_active_user() and public.has_role(array['owner','admin','cashier','technician']::public.app_role[]));drop policy if exists "Active users read warranty claims" on public.warranty_claims;create policy "Active users read warranty claims" on public.warranty_claims for select to authenticated using(public.is_active_user());drop policy if exists "Staff manage warranty claims" on public.warranty_claims;create policy "Staff manage warranty claims" on public.warranty_claims for all to authenticated using(public.is_active_user() and public.has_role(array['owner','admin','cashier','technician']::public.app_role[])) with check(public.is_active_user() and public.has_role(array['owner','admin','cashier','technician']::public.app_role[]));grant select,insert on public.receivable_payments to authenticated;grant select,insert,update,delete on public.warranties,public.warranty_claims to authenticated;
create or replace function public.register_receivable_payment(p_sale_id uuid,p_amount numeric,p_method text,p_paid_at date default current_date,p_reference text default null,p_notes text default null,p_cash_session_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_user uuid:=auth.uid();v_payment uuid;v_total numeric(14,2);v_paid numeric(14,2);v_status public.sale_status;v_method public.payment_method;v_movement uuid;begin if v_user is null or not public.is_active_user() or not public.has_role(array['owner','admin','cashier']::public.app_role[]) then raise exception 'No tienes permisos para registrar abonos.';end if;if p_amount is null or p_amount<=0 then raise exception 'El abono debe ser mayor que cero.';end if;begin v_method:=p_method::public.payment_method;exception when others then raise exception 'Medio de pago no válido.';end;select total,status into v_total,v_status from public.sales where id=p_sale_id for update;if not found or v_status<>'completed' then raise exception 'La venta no existe o no está completada.';end if;select coalesce((select sum(amount) from public.sale_payments where sale_id=p_sale_id),0)+coalesce((select sum(amount) from public.receivable_payments where sale_id=p_sale_id),0) into v_paid;if p_amount>v_total-v_paid then raise exception 'El abono supera el saldo pendiente.';end if;if v_method='cash' then if p_cash_session_id is null or not exists(select 1 from public.cash_sessions where id=p_cash_session_id and closed_at is null) then raise exception 'Para registrar efectivo debes seleccionar una caja abierta.';end if;else p_cash_session_id:=null;end if;insert into public.receivable_payments(sale_id,amount,method,paid_at,reference,notes,cash_session_id,created_by) values(p_sale_id,p_amount,v_method,p_paid_at,p_reference,p_notes,p_cash_session_id,v_user) returning id into v_payment;if v_method='cash' then insert into public.cash_movements(cash_session_id,kind,amount,category,description,reference,created_by) values(p_cash_session_id,'income',p_amount,'Abono de cartera','Abono a venta #'||(select sale_number from public.sales where id=p_sale_id),p_reference,v_user) returning id into v_movement;update public.receivable_payments set cash_movement_id=v_movement where id=v_payment;end if;insert into public.audit_log(actor_id,action,entity,entity_id,details) values(v_user,'insert','receivable_payments',v_payment::text,jsonb_build_object('sale_id',p_sale_id,'amount',p_amount,'method',v_method,'paid_at',p_paid_at));return v_payment;end $$;grant execute on function public.register_receivable_payment(uuid,numeric,text,date,text,text,uuid) to authenticated;
create or replace function public.audit_warranty_changes() returns trigger language plpgsql security definer set search_path=public as $$ declare v_id text;v_details jsonb;begin if TG_OP='DELETE' then v_id:=old.id::text;v_details:=jsonb_build_object('old',to_jsonb(old));elsif TG_OP='UPDATE' then v_id:=new.id::text;v_details:=jsonb_build_object('old',to_jsonb(old),'new',to_jsonb(new));else v_id:=new.id::text;v_details:=jsonb_build_object('new',to_jsonb(new));end if;insert into public.audit_log(actor_id,action,entity,entity_id,details) values(auth.uid(),lower(TG_OP),TG_TABLE_NAME,v_id,v_details);if TG_OP='DELETE' then return old;else return new;end if;end $$;drop trigger if exists audit_warranties_changes on public.warranties;create trigger audit_warranties_changes after insert or update or delete on public.warranties for each row execute function public.audit_warranty_changes();drop trigger if exists audit_warranty_claims_changes on public.warranty_claims;create trigger audit_warranty_claims_changes after insert or update or delete on public.warranty_claims for each row execute function public.audit_warranty_changes();